class Solution:
    def toHex(self, num: int) -> str:
        value = num & 0xffffffff
        digits, result = '0123456789abcdef', []
        for shift in range(28, -1, -4):
            nibble = (value >> shift) & 15
            if nibble or result:
                result.append(digits[nibble])
        return ''.join(result) or '0'
